   const candidates=[];for(let j=0;j<WARRIOR_MARK.length;j+=2)candidates.push([WARRIOR_MARK[j],WARRIOR_MARK[j+1]]);
   // Shuffle the 7,000 hand-traced logo points: no repeated random clumps.
   for(let k=candidates.length-1;k>0;k--){const j=Math.floor(rand()*(k+1));[candidates[k],candidates[j]]=[candidates[j],candidates[k]];}
