 for(let i=0;i<count;i++){
  // Start as a murmuration, then converge organically.
  const theta=rr(0,Math.PI*2),r=rr(0,1);const x=sceneIndex===0?537+Math.cos(theta)*r*24:points[i].x+Math.cos(theta)*r*20,y=sceneIndex===0?437+Math.sin(theta)*r*20:points[i].y+Math.sin(theta)*r*20;
  particles.push({x,y,vx:rr(-1.6,1.6),vy:rr(-1.6,1.6),tx:points[i].x,ty:points[i].y,growthAt:points[i].growthAt||0,seed:rr(0,4000),shade:Math.floor(rr(0,PAL.length)),size:rr(.90,1.72),freedom:rand()<.07,lawTone:points[i].lawTone||0,depthSeed:rr(-1,1),depth:0});
 }
