 const s=scenes[i];$('#title').innerHTML=s.title;$('#copy').textContent=s.subtitle;$('#sceneNo').textContent=`CHAPTER ${s.number} / 05`;$('#sceneTitle').textContent=s.aside;$('#sceneDesc').textContent=s.detail;
